using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry.Gluing;

internal sealed class ActualEndpointReturnClassesDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Geometry/Gluing/ActualEndpointReturnClasses.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The classes of literal pure endpoints in the original point quotient correspond to the four actual fiber return-cycle quotients.",
        H("Original pure endpoints and actual return classes"),
        Blocks(
            Def("Flag", "The original label fiber",
                "A flag is an original ordered dart (omega,j,k) with j different from k and with the original corner label equal to nu. No endpoint sorting, different quotient or orbit enlargement is performed."),
            Def("delta", "Pure barycentric coordinates",
                "The coordinate at the selected tip is exactly one; all other coordinates are zero."),
            Def("endpoint", "The endpoint in the original carrier",
                "The original corner and its delta coordinates satisfy the unchanged Carrier: the omitted coordinate is zero, coordinates are nonnegative, their sum is one and their corner label is nu."),
            Def("Endpoints", "The pure endpoint locus",
                "This is the range of the literal endpoint map inside the full original carrier, before any quotient is taken."),
            Def("PointQuotient", "The original point quotient",
                "The quotient uses exactly EqvGen of the original guarded Step. It includes every original intermediate in a chain."),
            Def("flagSetoid", "The restricted original dart relation",
                "This is the pullback of the original DartRelated setoid to Flag. The theorem proves flag and label saturation before identifying it with the generated restricted relation."),
            Def("FlagQuotient", "Original endpoint flag classes",
                "Take the quotient of the nu-restricted flags by the full original dart relation."),
            Def("endpointClassMap", "The actual map to point classes",
                "Send each flag class to its literal endpoint class in the unchanged point quotient. Full bidirectional relation correspondence makes this map injective."),
            Def("Root", "Four distinct root fibers",
                "In row order L0,L1,H2,H0, a root sheet has original corner number 0,1,2,0 respectively, and that corner has label nu. These fibers remain distinct until an explicit equivalence transports them."),
            Def("returnPerm", "Actual return permutations",
                "The two low rows act by ell = v inverse times u squared; the two high rows by h = v squared times u. These are permutations of the original arbitrary right action."),
            Def("rootReturn", "Returns in the selected root fibers",
                "Prove preservation of the original nu label, then restrict the actual return permutation to its Root. The construction allows nonfaithful, nonfree and nontransitive finite actions."),
            Def("RootCycles", "Actual root-return cycle classes",
                "The cycle quotient is SameCycle of the actual restricted permutation. Every fixed point is a cycle; period one is included."),
            Def("ReturnClasses", "The four row quotients",
                "The dependent sum over four rows contains their actual root-return cycle quotients. It counts no other nu component and uses no order of an acting group element."),
            Def("rootFlag", "Actual phase-zero flags",
                "Encode a sheet in its original row at phase zero, preserving the original ordered endpoint pair and label."),
            Def("returnClassMap", "The component enumeration consumer",
                "Map each actual root-return class through its phase-zero flag to the original flag quotient. Injectivity follows from the full component enumeration and unique row/phase classification. Surjectivity pulls an arbitrary valid dart back by its actual phase offset and uses an occurrence of the same enumeration to reach it from phase zero."),
            Def("returnClassesEquiv", "Faithful return-class correspondence",
                "The equivalence uses that actual map and its proved bijectivity. The proof reduces natural returns modulo the least positive pointPeriod supplied by actual_component_enumeration; it does not substitute the order of the return word."),
            Def("EndpointClasses", "Marked classes in the original quotient",
                "These are the range of the injective endpointClassMap, an actual subset of the original point quotient."),
            Def("endpointClassesEquiv", "Return classes as actual point classes",
                "Compose the return-class equivalence with the injective original endpoint map onto its range. Its representative formula commutes with the original point quotient map."),
            Def("ZeroFiber", "The slot-zero fiber",
                "O_nu contains exactly those original sheets whose corner (omega,0) has label nu."),
            Def("rootToZero", "Preserving labels under corner normalization",
                "For row c, act by u to the power of its original root corner number. The public actual_corner_orbit_iff proves this is an equivalence to O_nu with inverse action by the inverse power. The proof keeps arbitrary groups and the same original corner quotient."),
            Def("zeroReturn", "Conjugated actual returns",
                "Conjugate rootReturn by rootToZero. The same-cycle relation is transported in both directions by this equivalence."),
            Def("normalizedWord", "The four words in row order",
                "The words are inverse s, inverse t, s times k, and k times t, using the original sWord,tWord,kWord. Thus they are c1, inverse c3, c2, inverse c4. Inverting a permutation preserves SameCycle; the conventional final c1,c2,c3,c4 order is the row order 0,2,1,3."),
            Def("rowOrder", "The conventional boundary order",
                "The involutive row permutation (0,2,1,3) transports the original L0,L1,H2,H0 order into c1,c2,c3,c4 order."),
            Def("boundaryWord", "Original boundary words",
                "In conventional order the words are inverse s, s times k, t, inverse of k times t. They act on the same slot-zero fiber O_nu."),
            Def("boundaryReturn", "Actual oriented boundary returns",
                "Reorder the proved zeroReturn permutations and invert the last two. The theorem proves that these permutations act by the corresponding original boundaryWord."),
            Def("BoundaryCycles", "Cycles of the actual boundary returns",
                "Use SameCycle of boundaryReturn on O_nu, retaining fixed points and repeated point classes."),
            Def("BoundaryClasses", "Four boundary cycle quotients",
                "This dependent sum uses the actual returns c1,c2,c3,c4 on the selected original slot-zero fiber."),
            Def("boundaryClassesEquiv", "Fiber, conjugacy and inverse correspondence",
                "Quotient.congr transports the proved rootToZero equivalences; Mathlib's sameCycle_inv justifies the inverse directions; sigma congruence applies the row permutation. These are actual class equivalences, not count substitutions."),
            Def("boundaryEndpointEquiv", "Boundary cycles as original endpoint classes",
                "Compose the actual boundary-class equivalence with the original endpoint-class equivalence. The theorem includes the commuting equality with the unchanged point quotient."),
            Describe.Lean(DescribeId.Create("actual-endpoint-return-classes"),
                DeclarationHandle.Create(Prefix + "actual_endpoint_return_classes"),
                H("Full endpoint restriction and actual return classes"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("For every group G, arbitrary right action on a finite Omega, u,v in G and original corner class nu, two literal pure endpoints are Related if and only if their flags are DartRelated. The full original dart chain is equivalent to its nu-restricted flag chain, and the endpoint locus is saturated under every full original point chain. For any two points of the pure endpoint locus, the full original Related relation holds exactly when those points are connected by EqvGen of the original Step restricted to that locus.")),
                    Paragraph(Text("The return-class equivalences above identify the actual endpoint classes with the four actual root-fiber cycle quotients and commute with the original point quotient. The theorem retains the existing positive point period and exact tour period three times that period, and proves the slot-zero conjugacy and both directions of same-cycle transport.")),
                    Paragraph(Text("Point-relation reflection consumes actual_guarded_point_analysis through the strict neighborhood of the source endpoint. Restriction and saturation keep all transitive intermediates. The cycle correspondence consumes the exhaustion, unique ordered-pair classification and indexed occurrence formula of actual_component_enumeration. No component enumeration or minimal-period theorem is reproved.")),
                    Paragraph(Text("Repeated quotient classes, period one, nonregular and nonfaithful actions are allowed. If Omega is empty, the statement quantified over its original nu is vacuous. The two low rows share a return word but have different root fibers; they are identified with slot zero only by the proved corner normalization equivalences.")),
                    Paragraph(Text("This source-specific inference is derived from the original corner-pairing suppliers and pinned Mathlib relation and permutation APIs. It makes no literature-priority claim. It is an endpoint and cycle-class correspondence: a faithful polygon adapter, invariance under complete polygon normalization, manifold structure, orientation, Euler characteristic and genus require separate constructions and proofs."))),
                DescribeRole.Theorem),
            Paragraph(Text("Application: pure endpoints for an arbitrary raw face pairing. Let T be any type and P:RawFacePairing(T), retaining its fixed-point-free involutive facePair on T times Fin(4), its original three-slot faceMap and the paired inverse-slot law. Use the same P throughout. For x=(t,f) paired to (t′,g), the whole-vertex permutation is the derived sigma_x=frame_g^(-1) composed with Option(faceMap_x) composed with frame_f; Option(faceMap_x) fixes the omitted-face marker. These are the actual face-slot frames, not additional transport data. The compatible corner pairing is obtained by the same fixed frame changes, and label(t,j) is its corner quotient label. Fix any such label nu. No finiteness, topology, coloring or group action is required for this application.")),
            Paragraph(Text("The full corner carrier consists of x=((t,j),b) with b_j=0, all b_i>=0, sum_i b_i=1 and label(t,j)=nu. Its Point type retains the entire closed triangle. A raw Dart is the ordered triple d=((t,j),k), including raw triples with j=k; Flag(P,nu) restricts it to j!=k and label(t,j)=nu. Reuse the literal delta_k(i), equal to 1 at k and 0 elsewhere, and send a flag to endpoint(d)=((t,j),delta_k). This satisfies the full carrier conditions. The endpoint map is injective before any quotient: equality preserves the original corner, and evaluating the equal delta functions at k forces the tips to agree.")),
            Paragraph(Text("For every raw Dart d=((t,j),k), crossing face f sends it to dartMove_f(d)=((t′,sigma_(t,f)(j)),sigma_(t,f)(k)), where t′ is the tetrahedron of facePair(t,f). DartStep(d,e) requires f!=j, f!=k and e=dartMove_f(d). Define DartRelated as EqvGen of this relation on the full raw Dart type. Permutation injectivity preserves j!=k. On unequal darts, the actual carrier transport also preserves the corner label. Consequently, for every full raw DartRelated chain and every nu, membership in Flag(P,nu) is equivalent at its two ends. This invariant is proved before restricting the chain to the flag subtype.")),
            Paragraph(Text("Use the same full Point generator Step(x,y): there is f different from the omitted corner j, b_f=0, and y=move_f(x), with the barycentric vector transported by precomposition with sigma_(t,f)^(-1). At a literal endpoint b=delta_k, the zero-face condition b_f=0 is exactly f!=k. The permutation identity delta_k composed with sigma^(-1)=delta_(sigma(k)) then gives Step(endpoint(d),endpoint(e)) if and only if DartStep(d,e). The forward implication recovers the new tip by evaluating the target delta at sigma(k); it keeps the original face guard as well as the original corner.")),
            Paragraph(Text("Let Endpoints(P,nu) be the range of the literal endpoint map inside the full Point carrier, and Related=EqvGen(Step) on that full carrier. Endpoint membership is preserved in both directions by each Step. Forward transport sends delta_k to delta_(sigma(k)); backward transport recovers the source delta with sigma^(-1), using the target carrier to retain the unequal-corner guard and label. Induction through the complete EqvGen proves that Related(x,y) implies x is an endpoint if and only if y is an endpoint. In particular every intermediate connected to a source endpoint in a full Point chain is itself a literal endpoint.")),
            Paragraph(Text("For any flags d,e, the resulting full relation correspondence is Related(endpoint(d),endpoint(e)) if and only if DartRelated(d,e). To reflect a Point chain, lift its generator steps by the guarded equivalence, its reflexive case by endpoint injectivity, and its transitive case by the endpoint representative of the intermediate supplied by saturation. In the other direction, flag invariance keeps the full raw Dart chain inside Flag, and the same generator equivalence maps the resulting flag chain into the full Point relation. Both directions retain all original intermediates.")),
            Paragraph(Text("The two restriction statements are precise consequences of saturation. For flags d,e, their underlying raw darts are DartRelated exactly when d and e are in EqvGen of DartStep restricted to Flag(P,nu). For x,y in the subtype Endpoints(P,nu), Related(x,y) holds exactly when x and y are in EqvGen of Step restricted to that endpoint subtype. In each lifting induction, membership of a transitive intermediate follows from the corresponding full-chain invariant; projecting a restricted chain back gives the converse. Thus the full raw closure and the generated subtype closure agree on their stated saturated carriers.")),
            Paragraph(Text("For one fixed ordered flag d, its endpoint component is fully saturated in the entire Point carrier: Related(endpoint(d),y) if and only if there is a flag e with DartRelated(d,e) and endpoint(e)=y. Indeed full-chain saturation first supplies an endpoint representative e for y, and full relation reflection supplies its raw Dart relation to d; the converse is the same reflection followed by the representative equality. This describes the whole Point equivalence class of the selected endpoint, rather than only its intersection with a chosen list of endpoints.")),
            Paragraph(Text("Finally use the already established cap bridge for this same arbitrary P. Its affine map toTruncation sends ((t,j),b) to (t,a), with a_i=(3/4 if i=j, else 0)+b_i/4, in the unchanged truncated carrier 0<=a_i<=3/4 and sum_i a_i=1. TruncatedStep crosses an original face with a_f=0 using the same sigma. The cap bridge proves Related(x,y) if and only if EqvGen(TruncatedStep)(toTruncation(x),toTruncation(y)), where that closure is taken on the full truncated carrier. Composing with endpoint reflection gives DartRelated(d,e) if and only if the two truncated literal endpoints are related by that full ambient closure. The cap bridge retains every ambient intermediate through saturation of the same nu cap; no finite-T or topological part of that supplier is needed.")),
            Paragraph(Text("The endpoint conclusions above retain the endpoint order without a hypothesis forbidding a chain from exchanging endpoints. To compare with an original global edge, now forget that order explicitly. For an unequal raw dart d=((t,j),k), set occ(d)=(t,edgeIndex(j,k)) in the original Occurrence(T)=T times Fin(6), and set swap(d)=((t,k),j). The existing six-edge table identifies edgeIndex(j,k) with an unordered pair of distinct vertices. Every actual DartStep projects to the original P.edgeStep: choose the slot n in the crossed face f containing that same local edge, and use the derived sigma endpoint law to identify its image with the original faceMap(f,n). Full raw DartRelated chains therefore project to full EqvGen(P.edgeStep), with unequal endpoints preserved along every intermediate.")),
            Paragraph(Text("Conversely fix the actual source face x=(t,f) and edge slot n witnessing an original edgeStep, and any ordered endpoint dart d with occ(d)=(t,faceEdge(f,n)). The same six-edge table proves f differs from both endpoints of d. The lifted dart is exactly dartMove_f(d); it uses this same face and slot and has occurrence ((P.facePair(x)).tetrahedron,faceEdge((P.facePair(x)).face,P.faceMap(x,n))). Thus the lift retains the supplied port, rather than choosing an unrelated adjacency witness. The inverse move crosses the paired face and returns the same dart, by the paired inverse-slot law and sigma_(P.facePair(x))=sigma_x^(-1). The original edgeStep is symmetric by those same paired laws.")),
            Paragraph(Text("Fix any unequal dart d0 and let Component(P,d0) consist of all unequal darts d with DartRelated(d0,d). Let OccurrenceFiber(P,occ(d0)) consist of every original occurrence o with P.edgeLabel(o)=P.edgeLabel(occ(d0)). Projection by occ gives a map from this ordered component into that whole original fibre, because the edge label is the quotient by the original full EqvGen(P.edgeStep). No finite list or selected subfibre replaces that quotient fibre.")),
            Paragraph(Text("This projection is surjective without a no-reversal hypothesis. Define Reach(o) to mean some dart in Component(P,d0) has occurrence o. The exact port lift proves Reach is preserved by an original edgeStep; symmetry gives preservation in the reverse direction. Reach is therefore invariant along the full EqvGen(P.edgeStep). Quotient exactness lifts the defining equality of any occurrence-fibre member to such a full chain from occ(d0). Since d0 witnesses Reach(occ(d0)), that chain supplies an ordered dart above the arbitrary member. Repeated local edge labels and arbitrary intermediate occurrences are retained.")),
            Paragraph(Text("For two unequal darts with the same occurrence, the original six-edge table gives precisely two possibilities: the darts agree, or one is swap of the other. Raw DartStep commutes with swap because the same sigma transports both endpoints, and hence so does its full EqvGen. Impose only the local no-edge-reversal condition at the chosen root d0: there is no full DartRelated chain from d0 to swap(d0). If two members of Component(P,d0) project to the same occurrence, the swap alternative would combine their component chains and swap-equivariance to give that forbidden root reversal. Thus this local condition makes the projection injective; no global no-reversal condition on all edges is assumed.")),
            Paragraph(Text("Under this local condition, the actual projection therefore induces Component(P,d0) equivalent to OccurrenceFiber(P,occ(d0)), and its forward representative is exactly the original occurrence occ(d), unchanged. Take nu to be the corner label at the omitted endpoint of d0. The full-chain flag invariant makes every dart in this component a Flag(P,nu), so the endpoint saturation and reflection above identify the same component with the entire Point equivalence class of the literal endpoint of d0. Its occurrence comparison is thus a statement about that original full class, with the local no-reversal hypothesis needed for bijectivity. Without that hypothesis, the whole-fibre surjection remains the conclusion.")),
            Paragraph(Text("These applications require neither finite T nor topology, coloring, a group action or fixture data. The endpoint restriction and the conditional ordered-component/occurrence-fibre equivalence do not yet enumerate a successor cycle or prove a minimal period, nor construct a disk, fan, atlas or manifold neighborhood. In particular a bijection with the original occurrence fibre does not by itself supply a cyclic order or a topological chart. This exposition adds no mathematical declaration or theorem Describe and makes no code-retention or literature-priority claim.")))));

    private static DocumentBlock.Describe Def(string name, string heading, string text) =>
        Describe.Lean(DescribeId.Create("actual-endpoint-return-" + name.ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(heading),
            StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
            Blocks(Paragraph(Text(text))), DescribeRole.Definition);
}
